using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class InputMarksCompilerProof {
 static int Main(string[] a){try{byte[] ds=File.ReadAllBytes(a[0]),before=File.ReadAllBytes(a[1]),tokens=File.ReadAllBytes(a[2]),pref=File.ReadAllBytes(a[3]),after=File.ReadAllBytes(a[4]),ads=File.ReadAllBytes(a[5]);int count=BitConverter.ToInt16(ds,0x8798),notes=BitConverter.ToInt16(ds,0x8792),len=BitConverter.ToInt16(tokens,0);var rows=new List<float[]>();for(int i=0;i<count;i++){var p=new float[15];Buffer.BlockCopy(before,i*60,p,0,60);rows.Add(p);}var map=new int[notes];for(int i=1;i<notes;i++)map[i]=BitConverter.ToInt16(before,0x2b5a+i*2);var input=new float[len];Buffer.BlockCopy(tokens,2,input,0,len*4);var flags=new int[len];for(int i=0;i<len;i++)flags[i]=before.Length>0xe6dd+i*2?BitConverter.ToInt16(before,0xe6dc+i*2):0;float staff=BitConverter.ToSingle(ds,0x8780);var result=InputMarksCompiler.Apply(rows,map,input,flags,staff,0,200,BitConverter.ToSingle(ds,0x8040+((int)staff+1)*4),BitConverter.ToSingle(pref,16));if(result.Records.Count!=BitConverter.ToInt16(ads,0x8798))throw new Exception("Count");int words=0;for(int i=0;i<result.Records.Count;i++)for(int p=0;p<15;p++){if(BitConverter.ToInt32(BitConverter.GetBytes(result.Records[i][p]),0)!=BitConverter.ToInt32(after,i*60+p*4))throw new Exception("Record "+i+" P"+(p+1)+": "+result.Records[i][p]+" != "+BitConverter.ToSingle(after,i*60+p*4));words++;}Console.WriteLine("PASS "+words+" original mark-compiler words; opposite-side flags "+(before.Length>=65536?"captured":"zero (older unprefixed fixture)")+"");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
